(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.022-t*0.3)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.012+t*0.4)*10 + Math.cos((x-y)*0.015-t*0.35)*8;
  const w2y = Math.cos((x-y)*0.014+t*0.38)*9 + Math.sin((x+y)*0.011-t*0.42)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*80, 60+Math.cos(t*0.35)*40, 0.07, 2.2],
    [360+Math.cos(t*0.45)*90, 70+Math.sin(t*0.55)*50, 0.09, 1.8],
    [80+Math.sin(t*0.6+2)*70, 170+Math.cos(t*0.4+1)*60, 0.065, 2.5],
    [400+Math.cos(t*0.55+3)*60, 190+Math.sin(t*0.65+2)*50, 0.085, 1.6],
    [240+Math.sin(t*0.38+1)*130, 40+Math.cos(t*0.48+4)*60, 0.055, 2.8],
    [240+Math.cos(t*0.42+5)*110, 210+Math.sin(t*0.52)*70, 0.075, 2.0],
    [180+Math.sin(t*0.33+3)*60, 120+Math.cos(t*0.58+2)*90, 0.095, 1.4],
    [300+Math.cos(t*0.47+1)*70, 120+Math.sin(t*0.37+4)*80, 0.08, 2.1]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5);
    hS += Math.sin(d*f*1.3-t*sp*0.8+3.0)*0.5;
  }
  const act=aS/8, inh=iS/8, hab=hS/8;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.15 + Math.sin((sx-sy)*0.09-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.008)*0.3;
  const moebius = Math.sin(ang*2+dist*0.02-t*0.6)*Math.cos(ang*3-dist*0.015+t*0.4)*0.2;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral+ripple+hab*0.15+moebius)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin((sx-sy)*0.11-t*0.7)*0.3)*1.3)*0.25;
  const laplacian = (Math.sin(sx*0.22+t*0.5)*Math.sin(sy*0.22-t*0.4)+Math.cos(sx*0.18-sy*0.18+t*0.8))*0.15;
  const blend = reaction*0.65+cell*0.2+laplacian*0.15, v=blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,95],[15,90,120],[20,140,135],[45,175,140],
    [180,195,80],[220,165,55],[210,110,65],[175,60,70],[120,35,75],
    [65,22,65],[25,15,58],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.exp(-Math.abs(reaction)*2)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
